"""Public symbol accessors must agree with the expressions generated by models."""

import ast
import json
from pathlib import Path

from symbolica import S
from symbolica.community import hep, spenso


def test_model_references_work_with_native_coupling_expansion():
    model = hep.Model.standard_model()
    for coupling in model.couplings:
        assert model.expand_couplings(coupling.symbol) == coupling.expression
    for parameter in model.parameters:
        assert parameter.symbol.get_name().split("::")[-1] == parameter.name
    assert model.particle("e-").mass_expression == model.parameter("Me").symbol
    assert model.particle("a").mass_expression == 0
    assert model.parameter("MW").symbol != model.parameter("MW").expression
    definition = json.loads(model.to_json())
    definition["functions"] = [
        {"name": "square", "arguments": ["x"], "expression": "x^2"}
    ]
    custom = hep.Model.from_json(json.dumps(definition))
    assert custom.function("square").symbol.get_name().endswith("::square")


def test_public_heads_match_typed_tensors_and_generated_momenta():
    assert hep.Symbols.metric == spenso.TensorName.g().to_expression()
    assert hep.Symbols.gamma == spenso.TensorName.gamma().to_expression()
    assert hep.Symbols.lorentz(4) == spenso.Representation.mink(4).to_expression()
    amplitude = (
        hep.Model.phi4()
        .process(["phi", "phi"], ["phi", "phi"])
        .generate_amplitude(max_vertices=1)
    )
    for leg in amplitude.legs:
        assert leg.momentum == hep.Symbols.external_momentum(leg.index)
    # A user-defined symbol with the same short name cannot capture the accessor.
    assert S("user_notebook::P") != hep.Symbols.external_momentum


def test_notebook_sources_do_not_fetch_internal_namespace_symbols():
    examples = Path(__file__).parents[1] / "examples"
    for path in examples.rglob("*"):
        if path.suffix == ".ipynb":
            sources = [
                "".join(cell["source"])
                for cell in json.loads(path.read_text())["cells"]
                if cell["cell_type"] == "code"
            ]
        elif path.suffix == ".py" and "@app.cell" in path.read_text():
            sources = [path.read_text()]
        else:
            continue
        for source in sources:
            # Inspect calls rather than saved output or explanatory prose.
            for node in ast.walk(ast.parse(source)):
                if not isinstance(node, ast.Call):
                    continue
                name = getattr(node.func, "id", getattr(node.func, "attr", ""))
                if name not in {"S", "E", "TensorName", "parse"}:
                    continue
                for argument in node.args:
                    if isinstance(argument, ast.Constant) and isinstance(
                        argument.value, str
                    ):
                        assert not any(
                            prefix in argument.value
                            for prefix in ("UFO::", "gammalooprs::", "spenso::")
                        ), (path, node.lineno, argument.value)
